insert into public.products (id, slug, name, tagline, short_description, description, images, contents, packaging, dimensions, variants, tiers, bespoke_from, customisation, stock, status, featured, sort_order)
values
('luxe-bath-body-care-kit', 'luxe-bath-body-care-kit', 'The Luxe Bath & Body Care Kit', 'Crafted for your Diwali Dawn', 'Our signature five-piece collection in a premium magnetic box.', 'A luxurious self-care ritual, thoughtfully curated to nourish the skin, relax the body and elevate everyday moments.', array['/images/v5/luxe-tile.webp', '/images/v5/lux-box.webp', '/images/v5/lux-group.webp', '/images/v5/lux-scrubs.webp', '/images/v5/lux-oil.webp', '/images/v5/lux-soap.webp', '/images/v5/lux-candle.webp']::text[], '[{"name":"Body Scrub","size":"40 g","quantity":1,"note":"Exfoliates & nourishes"},{"name":"Face Scrub","size":"25 g","quantity":1,"note":"Gentle care for a natural glow"},{"name":"Body Oil","size":"30 ml","quantity":1,"note":"Deeply hydrates & revitalises"},{"name":"Handmade Soap","size":"75 g","quantity":1,"note":"Gentle cleansing with nourishing care"},{"name":"Soy Wax Scented Candle","quantity":1,"note":"Long-lasting fragrance for a calm, cozy ambiance"}]'::jsonb, 'Premium magnetic box with eco-friendly packaging.', null, null, '[{"min":1,"max":9,"unitPrice":1100},{"min":10,"max":25,"unitPrice":999},{"min":26,"max":null,"unitPrice":899}]'::jsonb, 100, 'Custom logo, corporate branding, personalised packaging, custom labels or tags and other bespoke requirements.', null, 'active', true, 1),
('tranquil-box', 'tranquil-box', 'The Tranquil Box', 'Simple. Soothing. Thoughtful.', 'Four handcrafted essentials, with a scented candle, in a magnet closure gift box.', 'The Tranquil Box is a calming blend of handcrafted self-care essentials, curated to nourish, relax and restore. A meaningful gift that brings moments of peace and well-being.', array['/images/products/set-tranquil.webp', '/images/products/tranquil-box-open-4-products.webp', '/images/products/floral-gift-boxes-stacked.webp']::text[], '[{"name":"Artisanal Soap","size":"75 g approx","quantity":1,"note":"Gentle & Nourishing"},{"name":"Aromatic Ubtan","size":"50 g approx","quantity":1},{"name":"Aromatic Body Oil","size":"35 ml","quantity":1},{"name":"Scented Candle","quantity":1}]'::jsonb, 'Thoughtfully packed in our signature Sacred Basil magnet closure gift box.', '6 × 4 × 2 inch (15.2 × 10.2 × 5 cm)', null, '[{"min":1,"max":5,"unitPrice":549},{"min":6,"max":25,"unitPrice":524},{"min":26,"max":null,"unitPrice":499}]'::jsonb, 100, 'Customisation available with your logo and message.', null, 'active', true, 2),
('serenity-box', 'serenity-box', 'The Serenity Box', 'Simple. Soothing. Thoughtful.', 'Three calming essentials in our signature floral gift box.', 'The Serenity Box is a calming blend of handcrafted self-care essentials, curated to nourish, relax and restore. A meaningful gift that brings moments of peace and well-being.', array['/images/products/set-serenity.webp', '/images/products/serenity-box-open-3-products.webp', '/images/products/floral-gift-boxes-stacked.webp']::text[], '[{"name":"Artisanal Soap","size":"70 g approx","quantity":1,"note":"Gentle & Nourishing"},{"name":"Aromatic Body Oil","size":"35 ml","quantity":1},{"name":"Aromatic Bath Powder","size":"50 g approx","quantity":1}]'::jsonb, 'Thoughtfully packed in our signature Sacred Basil gift box.', '4 × 4 × 2 inch (10.2 × 10.2 × 5 cm)', null, '[{"min":1,"max":5,"unitPrice":449},{"min":6,"max":25,"unitPrice":424},{"min":26,"max":null,"unitPrice":399}]'::jsonb, 100, 'Customisation of the gift box, contents and message card.', null, 'active', true, 3),
('festive-ritual', 'festive-ritual-box-pouch', 'The Festive Ritual Box / Pouch', 'Simple. Soothing. Thoughtful.', 'Three handcrafted essentials in a festive box or an organza pouch.', 'The Festive Ritual Box/Pouch is a thoughtful blend of handcrafted self-care essentials, curated to nourish, relax and restore. A meaningful gift that brings moments of peace and well-being.', array['/images/products/set-festive.webp', '/images/products/festive-ritual-box-red.webp', '/images/products/festive-ritual-organza-pouch.webp']::text[], '[{"name":"Artisanal Soap","size":"75 g approx","quantity":1,"note":"Gentle & Nourishing"},{"name":"Aromatic Ubtan","size":"50 g approx","quantity":1},{"name":"Aromatic Body Oil","size":"35 ml","quantity":1}]'::jsonb, 'Thoughtfully packed in our signature Sacred Basil box or pouch.', null, '[{"id":"box","name":"Festive box"},{"id":"pouch","name":"Organza pouch"}]'::jsonb, '[{"min":1,"max":5,"unitPrice":279},{"min":6,"max":25,"unitPrice":249},{"min":26,"max":null,"unitPrice":229}]'::jsonb, 100, 'Customisation available with your logo and message.', null, 'active', true, 4)
